const r = await fetch(
  `https://api.github.com/repos/${repo.trim()}/contributors?per_page=15`,
);
const j = await r.json();
Array.isArray(j)
  ? j.map((c) => ({ login: c.login, commits: c.contributions }))
  : j.message;

pulse.code:
// /stats endpoints return 202 while GitHub computes them — the canvas says so
const r = await fetch(
  `https://api.github.com/repos/${repo.trim()}/stats/participation`,
);
const weeks = r.status === 200 ? (await r.json()).all : null;
const draw = (ctx, { width: w, height: h }) => {
  ctx.fillStyle = "#242331";
  ctx.fillRect(0, 0, w, h);
  ctx.font = "10px monospace";
  if (!weeks) {
    ctx.fillStyle = "#8b89a0";
    ctx.fillText("stats warming up — nudge the repo name to retry", 10, h / 2);
    return;
  }
  const max = Math.max(...weeks, 1);
  const bw = w / weeks.length;
  ctx.fillStyle = "#d9a13f";
  weeks.forEach((v, i) => {
    const bh = (v / max) * (h - 30);
    ctx.fillRect(i * bw + 1, h - 8 - bh, Math.max(1, bw - 2), bh);
  });
  ctx.fillStyle = "#8b89a0";
  ctx.fillText(`commits / week — last year, peak ${max}`, 8, 13);
};
draw;
